class _MeasureLocals {
  String currentMeasurement = ''; // Str
  List<dynamic> measurementNames = <dynamic>['EVM', 'SEM']; // Strs
}

/// Sequence `Measure`.
Future<String> measure() async {
  final locals = _MeasureLocals();
  final run = ts.SequenceRun();

  try {
    // ── setup ──
    ts.eval(
      'Locals.Measurement_Names=Split(FileGlobals.Current_Sweep_Step.Input_and_Output.PARAMS.Test_Config,",")',
    ); // Split Test Names into Array

    // ── main ──
    // Only measure and apply DPD if its enabled for the current waveform configuration
    if (currentSweepStep.Input_and_Output.PARAMS.DPD_Enabled == true) {
      // .NET call: NationalInstruments.RFmx.SpecAnMX.RFmxSpecAnMX.Use Existing Object
      //   Existing Object <- FileGlobals.Device_Handles.RFmx_SpecAn_Signal_Session
      // .NET call: NationalInstruments.RFmx.SpecAnMX.RFmxSpecAnMX.SelectMeasurements
      //   selectorString <- FileGlobals.Configurations.Analyzer.RFmxSpecAn_Selector_String
      //   measurement <- "Dpd"
      //   enableAllTraces <- False
      ts.notExported(
        'dotNet call: NationalInstruments.RFmx.SpecAnMX.RFmxSpecAnMX.SelectMeasurements',
      ); // Select Single DPD measurement [Action]
      // Starts all measurements configured for the signal
      // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.Methods.DPD.dll
      // .NET call: NationalInstruments.ReferenceDesignLibraries.Methods.RFmxDPD.PerformMemoryPolynomial
      //   specAn <- FileGlobals.Device_Handles.RFmx_SpecAn_Signal_Session
      //   rfsgSession <- FileGlobals.Device_Handles.RFSG_Session
      //   mpConfig <- FileGlobals.Configurations.Analyzer.Measurements.DPD_MemoryPolynomial_Config
      //   referenceWaveform <- FileGlobals.Current_Sweep_Step.Loaded_Waveform
      //   selectorString <- FileGlobals.Configurations.Analyzer.RFmxSpecAn_Selector_String
      ts.notExported(
        'dotNet call: NationalInstruments.ReferenceDesignLibraries.Methods.RFmxDPD.PerformMemoryPolynomial',
      ); // Perform Memory Polynomial [Action]
      // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
      // Map Results: Statement with no expression
    }
    for (final element in ts.iterate(locals.measurementNames)) {
      locals.currentMeasurement = element as String;
      // Select the appropriate action based on which measurement is selected
      {
        final select1 = locals.currentMeasurement;
        var matched1 = false;
        // AMPM Method
        if (!matched1 && select1 == 'AMPM') {
          matched1 = true;
          // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.RFmxSpecAn.dll
          // .NET call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxSpecAn.SelectAndInitiateMeasurements
          //   specAn <- FileGlobals.Device_Handles.RFmx_SpecAn_Signal_Session
          //   autoLevelConfig <- FileGlobals.Configurations.Analyzer.Auto_Level_Config
          //   autoLevelBandwidth_Hz <- FileGlobals.Configurations.Analyzer.WLAN_Standard_Config.ChannelBandwidth_Hz
          //   enableTraces <- False
          //   selectorString <- FileGlobals.Configurations.Analyzer.RFmxSpecAn_Selector_String
          //   resultName <- ""
          ts.notExported(
            'dotNet call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxSpecAn.SelectAndInitiateMeasurements',
          ); // Initiate AMPM measurement [Action]
          // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.RFmxSpecAn.dll
          // .NET call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxSpecAn.FetchAmpm
          //   Return Value <- FileGlobals.Current_Sweep_Step.Results.RFmxSpecAn_AMPM_Results
          //   specAn <- FileGlobals.Device_Handles.RFmx_SpecAn_Signal_Session
          //   selectorString <- FileGlobals.Configurations.Analyzer.RFmxSpecAn_Selector_String
          ts.notExported(
            'dotNet call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxSpecAn.FetchAmpm',
          ); // SpecAn Fetch AMPM [Action]
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.AMPM_Mean_LinerGain_dB =
              currentSweepStep.Results.RFmxSpecAn_AMPM_Results.MeanLinearGain_dB; // Map Results
          currentSweepStep.Input_and_Output.MEAS.AMPM_Mean_RMS_EVM =
              currentSweepStep.Results.RFmxSpecAn_AMPM_Results.MeanRmsEvm_percent; // Map Results (cont.)
        }
        // Spectral Emission Mask Measurement
        if (!matched1 && select1 == 'SEM') {
          matched1 = true;
          // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.RFmxWLAN.dll
          // .NET call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.SelectAndInitiateMeasurements
          //   wlanSignal <- FileGlobals.Device_Handles.RFmx_WLAN_Signal_Session
          //   autoLevelConfig <- FileGlobals.Configurations.Analyzer.Auto_Level_Config
          //   enableTraces <- False
          //   selectorString <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          //   resultName <- ""
          ts.notExported(
            'dotNet call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.SelectAndInitiateMeasurements',
          ); // WLAN Initiate SEM [Action]
          // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.RFmxWLAN.dll
          // .NET call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.FetchSEM
          //   wlanSignal <- FileGlobals.Device_Handles.RFmx_WLAN_Signal_Session
          //   selectorString <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          ts.notExported(
            'dotNet call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.FetchSEM',
          ); // WLAN Fetch SEM [Action]
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.SEMMeasurementStatus =
              currentSweepStep.Results.RFmxWLAN_SEM_Results.measurementStatus; // Map Results
          currentSweepStep.Input_and_Output.MEAS.SEM_Absolute_Power_dBm =
              currentSweepStep.Results.RFmxWLAN_SEM_Results.AbsolutePower_dBm; // Map Results (cont.)
        }
        // EVM Measurement
        if (!matched1 && select1 == 'EVM') {
          matched1 = true;
          // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.RFmxWLAN.dll
          // .NET call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.SelectAndInitiateMeasurements
          //   wlanSignal <- FileGlobals.Device_Handles.RFmx_WLAN_Signal_Session
          //   autoLevelConfig <- FileGlobals.Configurations.Analyzer.Auto_Level_Config
          //   enableTraces <- False
          //   selectorString <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          //   resultName <- ""
          ts.notExported(
            'dotNet call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.SelectAndInitiateMeasurements',
          ); // WLAN Initiate ModAcc [Action]
          // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.RFmxWLAN.dll
          // .NET call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.FetchOFDMModAcc
          //   wlanSignal <- FileGlobals.Device_Handles.RFmx_WLAN_Signal_Session
          //   selectorString <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          ts.notExported(
            'dotNet call: NationalInstruments.ReferenceDesignLibraries.SA.RFmxWLAN.FetchOFDMModAcc',
          ); // WLAN Fetch OFDM ModAcc [Action]
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.RMS_EVM_Average_dB =
              currentSweepStep.Results.WLAN_OFDM_ModAcc_Results.CompositeRMSEVMMean_dB; // Map Results
          currentSweepStep.Input_and_Output.MEAS.Data_RMS_EVM_dB =
              currentSweepStep.Results.WLAN_OFDM_ModAcc_Results.CompositeDataRMSEVMMean_dB; // Map Results (cont.)
        }
      }
    }
  } finally {
    // ── cleanup ──
    // .NET assembly: ..\..\Builds\NationalInstruments.ReferenceDesignLibraries.SG.dll
    // .NET call: NationalInstruments.ReferenceDesignLibraries.SG.AbortGeneration
    //   rfsgHandle <- FileGlobals.Device_Handles.RFSG_Session
    //   timeOut_ms <- 1000
    ts.notExported(
      'dotNet call: NationalInstruments.ReferenceDesignLibraries.SG.AbortGeneration',
    ); // RFSG Abort Generation [Action]
  }

  return run.status;
}

/// Sequence `SequenceFileLoad`.
Future<String> sequenceFileLoad() async {
  final run = ts.SequenceRun();
  final dynamic firstLaunchMessageResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ButtonHit': 0,
    'Response': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of First Launch Message

  // popup title: NameOf(Step)
  // popup message: @"If this is your first time opening this example sequence, please make sure to check the following: | - To use the proper RF devices, in the Variable pane navigate to FileGlobals.Static_Station_Configs.Device_Names  |   and enter the device identifiers there.  | - When using a PXIe 5830/31 enter the respective portnames in FileGlobals.Configurations.Analyzer.Common_Config.SelectedPorts and in |   FileGlobals.Configurations.Generator.RFSGConfig.SelectedPorts. | - You can change the waveform configuration under FileGlobals.Static_Station_Configs.Waveform_Configs.  | - All other Analyzer and Generator configurations can be found in the Configurations Container. | - The sequence will write a CSV result file in <./DataFiles/Results/>. You can change the parameters and measurements written to the file in  |   FileGlobals.Current_Sweep_Step.Input_and_Output and by adapting the 'Map Results' expression step in the Measure subsequence. | Feel free to keep this message from appearing next time you load the sequence by removing the 'SequenceFileLoad' callback from the Sequences pane."
  // popup buttons: "OK"
  // First Launch Message [MessagePopup]: acts through ts.stepHost
  final popup = await ts.stepHost.messagePopup(
    title: 'First Launch Message',
    message:
        'If this is your first time opening this example sequence, please make sure to check the following:\n\n- To use the proper RF devices, in the Variable pane navigate to FileGlobals.Static_Station_Configs.Device_Names \n  and enter the device identifiers there. \n\n- When using a PXIe 5830/31 enter the respective portnames in FileGlobals.Configurations.Analyzer.Common_Config.SelectedPorts and in\n  FileGlobals.Configurations.Generator.RFSGConfig.SelectedPorts.\n\n- You can change the waveform configuration under FileGlobals.Static_Station_Configs.Waveform_Configs. \n\n- All other Analyzer and Generator configurations can be found in the Configurations Container.\n\n- The sequence will write a CSV result file in <./DataFiles/Results/>. You can change the parameters and measurements written to the file in \n  FileGlobals.Current_Sweep_Step.Input_and_Output and by adapting the \'Map Results\' expression step in the Measure subsequence.\n\nFeel free to keep this message from appearing next time you load the sequence by removing the \'SequenceFileLoad\' callback from the Sequences pane.',
    buttons: ['OK', '', '', '', '', ''],
  );
  firstLaunchMessageResult.ButtonHit = popup.buttonHit;
  firstLaunchMessageResult.Response = popup.response;
  firstLaunchMessageResult.Status = 'Done';
  run.record(firstLaunchMessageResult.Status);

  return run.status;
}
